/*
 * SM9 tests: every vector of testvectors/sm9-vectors.json (through test_sm9_vectors.h,
 * generated by tools/gen_sm9_vectors.py), the invalid points and scalars, the internal
 * arithmetic, random round trips, tampering, wrong IDs, keys and modes, and the key exchange.
 *
 * Includes sm9.c itself to reach the *_core variants that take a fixed r.
 */
#include "sm9.c"
#include "test_sm9_vectors.h"
#include <stdio.h>

#define COUNT_OF(a) (sizeof(a) / sizeof((a)[0]))

static int passed = 0, failed = 0;

static void check(const char *name, int cond) {
    if (cond) {
        passed++;
    } else {
        printf("  FAIL: %s\n", name);
        failed++;
    }
}

static void check_str(const char *name, const char *got, const char *want) {
    if (got != NULL && strcmp(got, want) == 0) {
        passed++;
    } else {
        printf("  FAIL: %s\n    got:  %s\n    want: %s\n", name, got ? got : "(null)", want);
        failed++;
    }
}

/* malloc'd bytes of a hex string; *len receives the count */
static uint8_t *unhex(const char *hex, size_t *len) {
    size_t n = strlen(hex) / 2;
    uint8_t *out = (uint8_t *)malloc(n + 1);
    *len = (size_t)hex_to_bytes(hex, out, n);
    return out;
}

static void scalar_of(const char *hex, uint64_t k[4]) {
    uint8_t be[32];
    hex_to_bytes(hex, be, 32);
    sm9_scalar_from_be(k, be);
}

static void upper(char *s) {
    for (; *s; s++) {
        if (*s >= 'a' && *s <= 'f') {
            *s = (char)(*s - 'a' + 'A');
        }
    }
}

/* ---------------------------------------------------------------- vectors */

static void test_sign_vectors(void) {
    size_t i;
    for (i = 0; i < COUNT_OF(sm9v_sign); i++) {
        char pub[SM9_G2_HEX_SIZE], upri[SM9_G1_HEX_SIZE], sig[SM9_SIGNATURE_HEX_SIZE];
        size_t len;
        uint8_t *msg = unhex(sm9v_sign[i].msg_hex, &len);
        uint64_t r[4];
        scalar_of(sm9v_sign[i].r, r);
        check("sign: master public", sm9_sign_master_public_key(sm9v_sign[i].mpri, pub));
        check_str("sign: master public value", pub, sm9v_sign[i].mpub);
        check("sign: user key", sm9_gen_sign_user_key(sm9v_sign[i].mpri, sm9v_sign[i].id,
                                                       sm9v_sign[i].hid, upri));
        check_str("sign: user key value", upri, sm9v_sign[i].upri);
        if (sm9v_sign[i].pairing_g != NULL) {
            g2_t ppub;
            fq12_t g;
            uint8_t gb[384];
            char gh[769];
            sm9_parse_g2(sm9v_sign[i].mpub, &ppub);
            sm9_pair(&g, &SM9_P1, &ppub);
            fq12_to_bytes(gb, &g);
            smx_hex_encode(gb, 384, gh, 'a');
            gh[768] = '\0';
            check_str("sign: e(P1, Ppub-s)", gh, sm9v_sign[i].pairing_g);
        }
        check("sign: with r",
              sm9_sign_core(msg, len, sm9v_sign[i].upri, sm9v_sign[i].mpub, r, sig));
        check_str("sign: signature", sig, sm9v_sign[i].sig);
        check("verify: vector", sm9_verify_bytes(msg, len, sm9v_sign[i].sig, sm9v_sign[i].id,
                                                 sm9v_sign[i].mpub, sm9v_sign[i].hid));
        check("verify: wrong hid", !sm9_verify_bytes(msg, len, sm9v_sign[i].sig, sm9v_sign[i].id,
                                                     sm9v_sign[i].mpub, sm9v_sign[i].hid + 1));
        check("verify: wrong id", !sm9_verify_bytes(msg, len, sm9v_sign[i].sig, "Mallory",
                                                    sm9v_sign[i].mpub, sm9v_sign[i].hid));
        check("verify: other message",
              !sm9_verify_bytes((const uint8_t *)"other", 5, sm9v_sign[i].sig, sm9v_sign[i].id,
                                sm9v_sign[i].mpub, sm9v_sign[i].hid));
        free(msg);
    }
}

static void test_encrypt_vectors(void) {
    size_t i;
    for (i = 0; i < COUNT_OF(sm9v_encrypt); i++) {
        char pub[SM9_G1_HEX_SIZE], upri[SM9_G2_HEX_SIZE];
        size_t len, out_len;
        uint8_t *msg = unhex(sm9v_encrypt[i].msg_hex, &len);
        uint8_t *plain;
        uint64_t r[4];
        char *ct;
        int mode;
        scalar_of(sm9v_encrypt[i].r, r);
        check("enc: master public", sm9_enc_master_public_key(sm9v_encrypt[i].mpri, pub));
        check_str("enc: master public value", pub, sm9v_encrypt[i].mpub);
        check("enc: user key", sm9_gen_enc_user_key(sm9v_encrypt[i].mpri, sm9v_encrypt[i].id,
                                                     sm9v_encrypt[i].hid, upri));
        check_str("enc: user key value", upri, sm9v_encrypt[i].upri);
        for (mode = 0; mode < 2; mode++) {
            const char *want = mode == 0 ? sm9v_encrypt[i].ct_stream : sm9v_encrypt[i].ct_sm4;
            ct = sm9_encrypt_core(msg, len, sm9v_encrypt[i].id, sm9v_encrypt[i].mpub,
                                  sm9v_encrypt[i].hid, mode, r);
            check_str(mode == 0 ? "enc: stream ciphertext" : "enc: SM4 ciphertext", ct, want);
            free(ct);
            plain = sm9_decrypt_bytes(want, sm9v_encrypt[i].id, sm9v_encrypt[i].upri, mode,
                                      &out_len);
            check("dec: vector", plain != NULL && out_len == len && memcmp(plain, msg, len) == 0);
            free(plain);
            plain = sm9_decrypt_bytes(want, sm9v_encrypt[i].id, sm9v_encrypt[i].upri, 1 - mode,
                                      &out_len);
            /*
             * The mode is not bound to the ciphertext. With a 16-byte C2, both modes split the
             * KDF output the same way (K1 16 bytes, K2 the next 32), so C3 checks out either
             * way and the "wrong" mode returns other bytes: inherent to the scheme.
             */
            check("dec: wrong mode", (plain == NULL && out_len == 0) ||
                                         (strlen(want) == 194 + 32 && out_len == 16 &&
                                          (out_len != len || memcmp(plain, msg, len) != 0)));
            free(plain);
            plain = sm9_decrypt_bytes(want, "Mallory", sm9v_encrypt[i].upri, mode, NULL);
            check("dec: wrong id", plain == NULL);
            free(plain);
        }
        free(msg);
    }
}

static void test_kem_vectors(void) {
    size_t i;
    for (i = 0; i < COUNT_OF(sm9v_kem); i++) {
        size_t n = sm9v_kem[i].key_len;
        char *key = (char *)malloc(2 * n + 1);
        char c[SM9_G1_HEX_SIZE], upri[SM9_G2_HEX_SIZE];
        uint64_t r[4];
        scalar_of(sm9v_kem[i].r, r);
        check("kem: user key",
              sm9_gen_enc_user_key(sm9v_kem[i].mpri, sm9v_kem[i].id, sm9v_kem[i].hid, upri));
        check_str("kem: user key value", upri, sm9v_kem[i].upri);
        check("kem: encapsulate", sm9_encapsulate_core(sm9v_kem[i].id, sm9v_kem[i].mpub, n,
                                                       sm9v_kem[i].hid, r, key, c));
        check_str("kem: key", key, sm9v_kem[i].key);
        check_str("kem: ciphertext", c, sm9v_kem[i].ct);
        check("kem: decapsulate",
              sm9_decapsulate(sm9v_kem[i].ct, sm9v_kem[i].id, sm9v_kem[i].upri, n, key));
        check_str("kem: decapsulated key", key, sm9v_kem[i].key);
        check("kem: wrong id gives another key",
              !sm9_decapsulate(sm9v_kem[i].ct, "Mallory", sm9v_kem[i].upri, n, key) ||
                  strcmp(key, sm9v_kem[i].key) != 0);
        free(key);
    }
}

static void test_exchange_vectors(void) {
    size_t i;
    for (i = 0; i < COUNT_OF(sm9v_exchange); i++) {
        char r_hex[SM9_SCALAR_HEX_SIZE], big_r[SM9_G1_HEX_SIZE], upri[SM9_G2_HEX_SIZE];
        SM9ExchangeResult b, a;
        uint64_t r[4];
        int hid = sm9v_exchange[i].hid;
        check("kx: key A", sm9_gen_enc_user_key(sm9v_exchange[i].mpri, sm9v_exchange[i].id_a,
                                                 hid, upri));
        check_str("kx: key A value", upri, sm9v_exchange[i].upri_a);
        check("kx: key B", sm9_gen_enc_user_key(sm9v_exchange[i].mpri, sm9v_exchange[i].id_b,
                                                 hid, upri));
        check_str("kx: key B value", upri, sm9v_exchange[i].upri_b);
        scalar_of(sm9v_exchange[i].r_a, r);
        check("kx: init A", sm9_exchange_init_core(sm9v_exchange[i].id_b, sm9v_exchange[i].mpub,
                                                   hid, r, r_hex, big_r));
        check_str("kx: R_A", big_r, sm9v_exchange[i].big_ra);
        check_str("kx: r_A", r_hex, sm9v_exchange[i].r_a);
        scalar_of(sm9v_exchange[i].r_b, r);
        check("kx: init B", sm9_exchange_init_core(sm9v_exchange[i].id_a, sm9v_exchange[i].mpub,
                                                   hid, r, r_hex, big_r));
        check_str("kx: R_B", big_r, sm9v_exchange[i].big_rb);

        b = sm9_exchange_respond(sm9v_exchange[i].key_len, sm9v_exchange[i].id_a,
                                 sm9v_exchange[i].id_b, sm9v_exchange[i].mpub,
                                 sm9v_exchange[i].upri_b, sm9v_exchange[i].r_b,
                                 sm9v_exchange[i].big_rb, sm9v_exchange[i].big_ra);
        check("kx: respond", b.success);
        check_str("kx: SK_B", b.shared_key, sm9v_exchange[i].sk);
        check_str("kx: S_B", b.s_b, sm9v_exchange[i].s_b);
        check_str("kx: S_2", b.s_2, sm9v_exchange[i].s_a);
        a = sm9_exchange_confirm(sm9v_exchange[i].key_len, sm9v_exchange[i].id_a,
                                 sm9v_exchange[i].id_b, sm9v_exchange[i].mpub,
                                 sm9v_exchange[i].upri_a, sm9v_exchange[i].r_a,
                                 sm9v_exchange[i].big_ra, sm9v_exchange[i].big_rb, b.s_b);
        check("kx: confirm", a.success);
        check_str("kx: SK_A", a.shared_key, sm9v_exchange[i].sk);
        check_str("kx: S_A", a.s_a, sm9v_exchange[i].s_a);
        check("kx: check", sm9_exchange_check(b.s_2, a.s_a));
        check("kx: check mismatch", !sm9_exchange_check(b.s_2, b.s_b));
        sm9_exchange_result_free(&a);
        a = sm9_exchange_confirm(sm9v_exchange[i].key_len, sm9v_exchange[i].id_a,
                                 sm9v_exchange[i].id_b, sm9v_exchange[i].mpub,
                                 sm9v_exchange[i].upri_a, sm9v_exchange[i].r_a,
                                 sm9v_exchange[i].big_ra, sm9v_exchange[i].big_rb, b.s_2);
        check("kx: wrong S_B refused, no key", !a.success && a.shared_key == NULL && !a.s_a[0]);
        sm9_exchange_result_free(&a);
        sm9_exchange_result_free(&b);
    }
}

/* ---------------------------------------------------------------- invalid input */

static void test_invalid_inputs(void) {
    const char *sp = sm9v_sign[0].mpub, *sk = sm9v_sign[0].upri;
    const char *ep = sm9v_encrypt[0].mpub, *ek = sm9v_encrypt[0].upri;
    char buf[SM9_G2_HEX_SIZE], key[65], sig[SM9_SIGNATURE_HEX_SIZE], r_hex[65];
    size_t i;
    SM9ExchangeResult res;

    for (i = 0; i < COUNT_OF(sm9v_invalid_g1); i++) {
        const char *v = sm9v_invalid_g1[i].value;
        char c[SM9_G1_HEX_SIZE];
        char *ct = sm9_encrypt("m", "Bob", v, 3, SM9_MODE_STREAM);
        check("invalid G1: as Ppub-e", ct == NULL);
        free(ct);
        check("invalid G1: as KEM key", !sm9_encapsulate("Bob", v, 16, 3, key, c));
        check("invalid G1: as KEM ciphertext", !sm9_decapsulate(v, "Bob", ek, 16, key));
        check("invalid G1: as signing key", !sm9_sign("m", v, sp, sig) && sig[0] == '\0');
        check("invalid G1: exchange init", !sm9_exchange_init("Bob", v, 2, r_hex, c));
        res = sm9_exchange_respond(16, "A", "B", ep, ek, sm9v_exchange[0].r_b,
                                   sm9v_exchange[0].big_rb, v);
        check("invalid G1: as R_A", !res.success && res.shared_key == NULL);
    }
    for (i = 0; i < COUNT_OF(sm9v_invalid_g2); i++) {
        const char *v = sm9v_invalid_g2[i].value;
        g2_t q;
        check("invalid G2: parse", !sm9_parse_g2(v, &q));
        check("invalid G2: sign master", !sm9_sign("m", sk, v, sig));
        check("invalid G2: verify master", !sm9_verify("m", sm9v_sign[0].sig, "Alice", v, 1));
        check("invalid G2: enc user key", !sm9_decapsulate(sm9v_kem[0].ct, "Bob", v, 32, key));
    }
    for (i = 0; i < COUNT_OF(sm9v_invalid_scalars); i++) {
        const char *v = sm9v_invalid_scalars[i].value;
        check("invalid scalar: sign master", !sm9_sign_master_public_key(v, buf) && !buf[0]);
        check("invalid scalar: enc master", !sm9_enc_master_public_key(v, buf));
        check("invalid scalar: sign user", !sm9_gen_sign_user_key(v, "a", 1, buf));
        check("invalid scalar: enc user", !sm9_gen_enc_user_key(v, "a", 3, buf));
        res = sm9_exchange_respond(16, sm9v_exchange[0].id_a, sm9v_exchange[0].id_b,
                                   sm9v_exchange[0].mpub, sm9v_exchange[0].upri_b, v,
                                   sm9v_exchange[0].big_rb, sm9v_exchange[0].big_ra);
        check("invalid scalar: as r_B", !res.success);
    }
    check("max master key", sm9_sign_master_public_key(SM9V_MAX_MASTER_KEY, buf) &&
                                sm9_enc_master_public_key(SM9V_MAX_MASTER_KEY, buf));
    /* the base points are valid points */
    check("P2 is a valid sign master key", sm9_sign("m", sk, SM9V_P2, sig));
    check("P1 is an enc master key", sm9_encapsulate("Bob", SM9V_P1, 16, 3, key, buf));

    check("hid -1", !sm9_gen_sign_user_key(sm9v_sign[0].mpri, "a", -1, buf));
    check("hid 256", !sm9_gen_enc_user_key(sm9v_sign[0].mpri, "a", 256, buf));
    check("hid 255", sm9_gen_enc_user_key(sm9v_sign[0].mpri, "a", 255, buf));
    check("bad mode", sm9_encrypt("m", "Bob", ep, 3, 2) == NULL);
    check("empty plaintext", sm9_encrypt("", "Bob", ep, 3, SM9_MODE_STREAM) == NULL &&
                                 sm9_encrypt("", "Bob", ep, 3, SM9_MODE_SM4) == NULL);
    check("KEM key_len 0", !sm9_encapsulate("Bob", ep, 0, 3, key, buf));
    check("NULL id", sm9_encrypt("m", NULL, ep, 3, 0) == NULL);
    res = sm9_exchange_respond(0, "A", "B", ep, ek, sm9v_exchange[0].r_b, sm9v_exchange[0].big_rb,
                               sm9v_exchange[0].big_ra);
    check("KX key_len 0", !res.success);
    res = sm9_exchange_respond(SM9_MAX_EXCHANGE_KEY_BYTES + 1, "A", "B", ep, ek,
                               sm9v_exchange[0].r_b, sm9v_exchange[0].big_rb,
                               sm9v_exchange[0].big_ra);
    check("KX key_len above 1 MiB", !res.success);
    check("KX check bad hex", !sm9_exchange_check("zz", sm9v_exchange[0].s_a));
}

/* Signatures and ciphertexts are lowercase only; keys accept either case. */
static void test_case_rules(void) {
    char sig[SM9_SIGNATURE_HEX_SIZE], mpub[SM9_G2_HEX_SIZE], upri[SM9_G2_HEX_SIZE], c[131];
    char key[65];
    char *ct;
    strcpy(sig, sm9v_sign[0].sig);
    strcpy(mpub, sm9v_sign[0].mpub);
    upper(mpub);
    check("upper master public accepted",
          sm9_verify("Chinese IBS standard", sig, "Alice", mpub, 1));
    upper(sig);
    check("upper signature rejected", !sm9_verify("Chinese IBS standard", sig, "Alice", mpub, 1));

    ct = (char *)malloc(strlen(sm9v_encrypt[0].ct_stream) + 1);
    strcpy(ct, sm9v_encrypt[0].ct_stream);
    strcpy(upri, sm9v_encrypt[0].upri);
    upper(upri);
    {
        char *p = sm9_decrypt(ct, "Bob", upri, SM9_MODE_STREAM);
        check_str("upper user key accepted", p, "Chinese IBE standard");
        free(p);
    }
    upper(ct);
    check("upper ciphertext rejected", sm9_decrypt(ct, "Bob", upri, 0) == NULL);
    ct[0] = '0';
    ct[1] = '4';
    check("upper C2 only rejected", sm9_decrypt(ct, "Bob", upri, 0) == NULL);
    free(ct);
    strcpy(c, sm9v_kem[0].ct);
    upper(c);
    check("upper KEM ciphertext rejected", !sm9_decapsulate(c, "Bob", sm9v_kem[0].upri, 32, key));
}

/* ---------------------------------------------------------------- internals */

static void test_arithmetic(void) {
    uint64_t a[4] = {0x1234567890ABCDEFULL, 7, 9, 0x0123456789ABCDEFULL}, b[4] = {99, 1, 2, 3};
    uint64_t ab[4], inv[4], one[4];
    fq12_t e, e1, e2, x;
    g1_t pa;
    g2_t qb;
    fq_t f, fi, prod;
    fq2_t f2, f2i, p2;

    /* Fq and Fq2 inverses */
    fq_to_mont(&f, a);
    fq_inv(&fi, &f);
    fq_mul(&prod, &f, &fi);
    check("fq inverse", fq_equal(&prod, &FQ_ONE) != 0);
    f2.a0 = f;
    fq_to_mont(&f2.a1, b);
    fq2_inv(&f2i, &f2);
    fq2_mul(&p2, &f2, &f2i);
    check("fq2 inverse", fq_equal(&p2.a0, &FQ_ONE) && fq_is_zero(&p2.a1));
    fq2_sqr(&p2, &f2);
    fq2_mul(&f2i, &f2, &f2);
    check("fq2 square", fq2_equal(&p2, &f2i) != 0);

    /* mod N */
    sm9n_mul(ab, a, b);
    sm9n_inv(inv, b);
    sm9n_mul(one, ab, inv);
    check("mod N inverse", memcmp(one, a, 32) == 0);

    /* bilinearity: e([a]P1, [b]P2) = e(P1, P2)^(ab) */
    g1_mul_ct(&pa, &SM9_P1, a);
    g1_normalize(&pa);
    g2_mul_ct(&qb, &SM9_P2, b);
    g2_normalize(&qb);
    sm9_pair(&e1, &pa, &qb);
    sm9_pair(&e, &SM9_P1, &SM9_P2);
    sm9_gt_pow(&e2, &e, ab);
    check("bilinearity", fq12_equal(&e1, &e2) != 0);
    sm9_gt_pow(&x, &e, SM9_N);
    fq12_set_one(&e2);
    check("e(P1, P2) has order N", fq12_equal(&x, &e2) != 0);
    fq12_sqr(&x, &e);
    fq12_cyclo_sqr(&e2, &e);
    check("cyclotomic squaring", fq12_equal(&x, &e2) != 0);
    fq12_inv(&x, &e);
    fq12_conj(&e2, &e);
    check("GT inverse is conjugate", fq12_equal(&x, &e2) != 0);

    /* constant-time and variable-time multiplication agree, including near N */
    {
        static const uint64_t ks[][4] = {{1, 0, 0, 0},
                                         {2, 0, 0, 0},
                                         {0xE56EE19CD69ECF24ULL, 0x49F2934B18EA8BEEULL,
                                          0xD603AB4FF58EC744ULL, 0xB640000002A3A6F1ULL},
                                         {0xE56EE19CD69ECF1FULL, 0x49F2934B18EA8BEEULL,
                                          0xD603AB4FF58EC744ULL, 0xB640000002A3A6F1ULL},
                                         {0xFFFFFFFFFFFFFFFFULL, 0xFFFFFFFFFFFFFFFFULL, 0, 0}};
        size_t i;
        for (i = 0; i < COUNT_OF(ks); i++) {
            g1_t c1, v1;
            g2_t c2, v2;
            g1_mul_ct(&c1, &SM9_P1, ks[i]);
            g1_mul_vt(&v1, &SM9_P1, ks[i]);
            g2_mul_ct(&c2, &SM9_P2, ks[i]);
            g2_mul_vt(&v2, &SM9_P2, ks[i]);
            check("g1 ct == vt", g1_equal(&c1, &v1) != 0);
            check("g2 ct == vt", g2_equal(&c2, &v2) != 0);
            check("g2 multiple in subgroup", g2_normalize(&c2) && g2_in_subgroup(&c2));
        }
        g1_mul_ct(&pa, &SM9_P1, SM9_N); /* N reduces to 0 */
        check("[N]P1 is infinity", fq_is_zero(&pa.z) != 0);
    }
    /* H1 of the standard's signing example, from GB/T 38635.5 A.2 */
    {
        uint64_t h[4];
        char hex[65];
        sm9_h1(h, "Alice", 1);
        sm9_scalar_to_hex(h, hex);
        check_str("H1(Alice || 01)", hex,
                  "2acc468c3926b0bdb2767e99ff26e084de9ced8dbc7d5fbf418027b667862fab");
    }
}

/* ---------------------------------------------------------------- random round trips */

static void test_round_trips(void) {
    static const size_t lengths[] = {1, 15, 16, 17, 31, 32, 33, 100, 1000};
    char spri[65], spub[SM9_G2_HEX_SIZE], epri[65], epub[SM9_G1_HEX_SIZE];
    char ds[SM9_G1_HEX_SIZE], de[SM9_G2_HEX_SIZE], de_a[SM9_G2_HEX_SIZE], sig[195];
    uint8_t msg[1000];
    size_t i, out_len;
    int mode;

    check("gen sign master", sm9_gen_sign_master_key(spri, spub));
    check("gen enc master", sm9_gen_enc_master_key(epri, epub));
    check("random sign user key", sm9_gen_sign_user_key(spri, "张三@example.com", 1, ds));
    check("random enc user key", sm9_gen_enc_user_key(epri, "", 3, de));
    check("random enc user key A", sm9_gen_enc_user_key(epri, "alice", 2, de_a));
    for (i = 0; i < sizeof(msg); i++) {
        msg[i] = (uint8_t)(i * 7 + 3);
    }
    for (i = 0; i < 3; i++) {
        check("random sign", sm9_sign_bytes(msg, i * 50, ds, spub, sig));
        check("random verify", sm9_verify_bytes(msg, i * 50, sig, "张三@example.com", spub, 1));
        check("random verify wrong hid", !sm9_verify_bytes(msg, i * 50, sig, "张三@example.com",
                                                           spub, 2));
        sig[100] = sig[100] == '0' ? '1' : '0';
        check("tampered S", !sm9_verify_bytes(msg, i * 50, sig, "张三@example.com", spub, 1));
        sig[100] = sig[100] == '0' ? '1' : '0';
        sig[3] = sig[3] == '0' ? '1' : '0';
        check("tampered h", !sm9_verify_bytes(msg, i * 50, sig, "张三@example.com", spub, 1));
    }
    for (mode = 0; mode < 2; mode++) {
        for (i = 0; i < COUNT_OF(lengths); i++) {
            size_t n = lengths[i], pos;
            char *ct = sm9_encrypt_bytes(msg, n, "", epub, 3, mode);
            uint8_t *p = sm9_decrypt_bytes(ct, "", de, mode, &out_len);
            check("round trip", ct != NULL && p != NULL && out_len == n && memcmp(p, msg, n) == 0);
            free(p);
            /* every part of the ciphertext is covered: C1, C3 and C2 */
            for (pos = 2; ct != NULL && pos < strlen(ct); pos += 61) {
                char saved = ct[pos];
                ct[pos] = saved == 'a' ? 'b' : 'a';
                p = sm9_decrypt_bytes(ct, "", de, mode, &out_len);
                check("tampered ciphertext", p == NULL && out_len == 0);
                free(p);
                ct[pos] = saved;
            }
            p = sm9_decrypt_bytes(ct, "x", de, mode, NULL);
            check("decrypt wrong id", p == NULL);
            free(p);
            p = sm9_decrypt_bytes(ct, "", de_a, mode, NULL);
            check("decrypt wrong key", p == NULL);
            free(p);
            if (ct != NULL) {
                ct[strlen(ct) - 2] = '\0';
                p = sm9_decrypt_bytes(ct, "", de, mode, NULL);
                check("truncated ciphertext", p == NULL);
                free(p);
            }
            free(ct);
        }
    }
    {
        char key[129], key2[129], c[131];
        check("random encapsulate", sm9_encapsulate("", epub, 64, 3, key, c));
        check("random decapsulate", sm9_decapsulate(c, "", de, 64, key2) && !strcmp(key, key2));
        check("decapsulate wrong key", !sm9_decapsulate(c, "", de_a, 64, key2) ||
                                           strcmp(key, key2) != 0);
    }
    {
        /* full key exchange between alice (A) and bob (B) */
        char de_b[SM9_G2_HEX_SIZE], ra[65], rb[65], big_ra[131], big_rb[131];
        SM9ExchangeResult b, a;
        check("kx bob key", sm9_gen_enc_user_key(epri, "bob", 2, de_b));
        check("kx init A", sm9_exchange_init("bob", epub, 2, ra, big_ra));
        check("kx init B", sm9_exchange_init("alice", epub, 2, rb, big_rb));
        b = sm9_exchange_respond(48, "alice", "bob", epub, de_b, rb, big_rb, big_ra);
        a = sm9_exchange_confirm(48, "alice", "bob", epub, de_a, ra, big_ra, big_rb, b.s_b);
        check("kx random", b.success && a.success && !strcmp(a.shared_key, b.shared_key) &&
                               sm9_exchange_check(b.s_2, a.s_a));
        sm9_exchange_result_free(&a);
        /* A thinks it talks to "carol": every value differs and S_B fails */
        a = sm9_exchange_confirm(48, "alice", "carol", epub, de_a, ra, big_ra, big_rb, b.s_b);
        check("kx wrong peer id", !a.success && a.shared_key == NULL);
        sm9_exchange_result_free(&a);
        /* the wrong private key for A */
        a = sm9_exchange_confirm(48, "alice", "bob", epub, de_b, ra, big_ra, big_rb, b.s_b);
        check("kx wrong key", !a.success);
        sm9_exchange_result_free(&a);
        sm9_exchange_result_free(&b);
    }
}

int main(void) {
    printf("=== SM9 internals ===\n");
    test_arithmetic();
    printf("=== SM9 vectors ===\n");
    test_sign_vectors();
    test_encrypt_vectors();
    test_kem_vectors();
    test_exchange_vectors();
    printf("=== SM9 invalid input ===\n");
    test_invalid_inputs();
    test_case_rules();
    printf("=== SM9 round trips ===\n");
    test_round_trips();
    printf("\n=== SM9 results: %d passed, %d failed ===\n", passed, failed);
    return failed > 0 ? 1 : 0;
}
